import{_ as o,o as s,c as t,a3 as a}from"./chunks/framework.vDgOMd_y.js";const g=JSON.parse('{"title":"Data locations","description":"","frontmatter":{},"headers":[],"relativePath":"en/configuration/data-locations.md","filePath":"en/configuration/data-locations.md"}'),n={name:"en/configuration/data-locations.md"};function i(d,e,l,c,r,p){return s(),t("div",null,[...e[0]||(e[0]=[a(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/configuration/data-locations.md for this page in Markdown format</div><h1 id="data-locations" tabindex="-1">Data locations <a class="header-anchor" href="#data-locations" aria-label="Permalink to &quot;Data locations&quot;">​</a></h1><p>Kimi Code CLI stores all runtime data — the config file, session history, login credentials, and diagnostic logs — under <code>~/.kimi-code/</code>. This page helps you understand where each type of data lives, what it is for, and how to clean up or relocate it when needed.</p><h2 id="data-root-directory" tabindex="-1">Data root directory <a class="header-anchor" href="#data-root-directory" aria-label="Permalink to &quot;Data root directory&quot;">​</a></h2><p>The default data root is <code>~/.kimi-code/</code>. The actual path varies by platform:</p><ul><li>macOS: <code>/Users/&lt;name&gt;/.kimi-code</code></li><li>Linux: <code>/home/&lt;name&gt;/.kimi-code</code></li><li>Windows: <code>C:\\Users\\&lt;name&gt;\\.kimi-code</code></li></ul><p>If you need to move the data directory elsewhere (for example, to isolate configs for different projects with independent environments), set <code>KIMI_CODE_HOME</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KIMI_CODE_HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.config/kimi-code&quot;</span></span></code></pre></div><p>Once set, <strong>all</strong> Kimi Code data — config, sessions, logs, OAuth credentials, Kimi-specific user Skills, global <code>AGENTS.md</code>, and more — lands under the new path. For the full reference on <code>KIMI_CODE_HOME</code>, see <a href="./env-vars.html">Environment variables</a>.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p><strong>Generic <code>.agents</code> resources</strong> stay under the real OS home so they can be shared across tools. For example, user-level generic Skills remain at <code>~/.agents/skills/</code>, while Kimi-specific user Skills move with <code>KIMI_CODE_HOME</code> as <code>$KIMI_CODE_HOME/skills/</code>.</p></div><h2 id="directory-layout" tabindex="-1">Directory layout <a class="header-anchor" href="#directory-layout" aria-label="Permalink to &quot;Directory layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$KIMI_CODE_HOME  (default: ~/.kimi-code)</span></span>
<span class="line"><span>├── config.toml             # User configuration</span></span>
<span class="line"><span>├── tui.toml                # Terminal UI preferences (including auto-update toggle)</span></span>
<span class="line"><span>├── AGENTS.md               # Global Kimi-specific agent instructions (optional)</span></span>
<span class="line"><span>├── mcp.json                # User-level MCP server declarations (optional)</span></span>
<span class="line"><span>├── skills/                 # Kimi-specific user-level Skills (optional)</span></span>
<span class="line"><span>├── plugins/</span></span>
<span class="line"><span>│   ├── installed.json      # Installed plugin records and enabled state</span></span>
<span class="line"><span>│   └── managed/            # Plugin copies installed from zip/local paths</span></span>
<span class="line"><span>├── session_index.jsonl     # Session index</span></span>
<span class="line"><span>├── credentials/            # OAuth credentials (dir 0700, files 0600)</span></span>
<span class="line"><span>│   ├── &lt;name&gt;.json</span></span>
<span class="line"><span>│   └── mcp/</span></span>
<span class="line"><span>│       └── &lt;key&gt;-&lt;suffix&gt;.json</span></span>
<span class="line"><span>├── sessions/               # Session data (see below)</span></span>
<span class="line"><span>│   └── &lt;workDirKey&gt;/&lt;sessionId&gt;/</span></span>
<span class="line"><span>├── bin/</span></span>
<span class="line"><span>│   ├── rg                  # managed ripgrep binary for Grep (rg.exe on Windows)</span></span>
<span class="line"><span>│   └── fd                  # managed fd binary for file references (fd.exe on Windows)</span></span>
<span class="line"><span>├── logs/</span></span>
<span class="line"><span>│   └── kimi-code.log       # Global diagnostic log</span></span>
<span class="line"><span>├── updates/</span></span>
<span class="line"><span>│   ├── latest.json</span></span>
<span class="line"><span>│   ├── install.json</span></span>
<span class="line"><span>│   ├── install.lock</span></span>
<span class="line"><span>│   └── rollout.log</span></span>
<span class="line"><span>└── user-history/</span></span>
<span class="line"><span>    └── &lt;md5(workDir)&gt;.jsonl</span></span></code></pre></div><h2 id="file-descriptions" tabindex="-1">File descriptions <a class="header-anchor" href="#file-descriptions" aria-label="Permalink to &quot;File descriptions&quot;">​</a></h2><p>Each top-level file under the data root serves a specific purpose; most are managed automatically by the CLI:</p><ul><li><strong><code>config.toml</code></strong>: the main runtime configuration file, storing user-level settings such as providers, models, and loop control. See <a href="./config-files.html">Configuration files</a>.</li><li><strong><code>tui.toml</code></strong>: terminal UI client preferences, including <code>[upgrade].auto_install</code> (auto-update, on by default). You can disable it in <code>/settings</code> or by manually setting <code>auto_install = false</code>.</li><li><strong><code>AGENTS.md</code></strong>: global Kimi-specific agent instructions. This file moves with <code>KIMI_CODE_HOME</code>; generic cross-tool instructions can still live under <code>~/.agents/AGENTS.md</code>.</li><li><strong><code>mcp.json</code></strong>: user-level MCP server declarations, merged with the project-local <code>.kimi-code/mcp.json</code> on startup. See <a href="./../customization/mcp.html">MCP</a>.</li><li><strong><code>skills/</code></strong>: Kimi-specific user-level Skills. This directory moves with <code>KIMI_CODE_HOME</code>; generic cross-tool Skills can still live under <code>~/.agents/skills/</code>. See <a href="./../customization/skills.html">Agent Skills</a>.</li><li><strong><code>plugins/installed.json</code></strong>: records installed plugins, each plugin&#39;s enabled state, and MCP server capability state changes made via <code>/plugins</code> or <code>/plugins mcp disable|enable</code>. Files installed from local paths or zip URLs are copied to <code>plugins/managed/&lt;id&gt;/</code>. See <a href="./../customization/plugins.html">Plugins</a>.</li><li><strong><code>credentials/</code></strong>: OAuth credential directory, with permissions <code>0o700</code> (directory) / <code>0o600</code> (files), readable and writable only by the current user. Managed provider credentials are stored as <code>credentials/&lt;name&gt;.json</code>; MCP server credentials are stored under <code>credentials/mcp/</code>. Credentials are written using an atomic flow (tmp → fsync → rename) to prevent corruption.</li></ul><h2 id="session-data" tabindex="-1">Session data <a class="header-anchor" href="#session-data" aria-label="Permalink to &quot;Session data&quot;">​</a></h2><p>Each session&#39;s data is stored under <code>sessions/&lt;workDirKey&gt;/&lt;sessionId&gt;/</code>, and a top-level <code>session_index.jsonl</code> index is maintained (one record per line, each containing <code>sessionId</code>, <code>sessionDir</code>, and <code>workDir</code>). <code>workDirKey</code> is a bucket name derived from the working directory path, in the format <code>wd_&lt;slug&gt;_&lt;first-12-chars-of-sha256&gt;</code>.</p><p>Inside each session directory:</p><ul><li><strong><code>state.json</code></strong>: session metadata including title, <code>lastPrompt</code>, creation/update timestamps, and <code>forkedFrom</code>.</li><li><strong><code>upcoming-goals.json</code></strong>: the TUI-only queue created by <code>/goal next &lt;objective&gt;</code>. It is not part of the agent conversation until a queued goal is promoted after the current goal completes.</li><li><strong><code>agents/main/wire.jsonl</code></strong>: the main Agent&#39;s complete communication record, used for session resumption and replay.</li><li><strong><code>agents/main/plans/</code></strong>: plan files written in Plan mode, named by plan id (<code>&lt;id&gt;.md</code>).</li><li><strong><code>agents/agent-0/</code> etc.</strong>: sub-Agent instance directories, each containing their own <code>wire.jsonl</code>.</li><li><strong><code>logs/kimi-code.log</code></strong>: diagnostic log for this session; only present when a diagnostic event occurs.</li><li><strong><code>tasks/</code></strong>: background task persistence — <code>tasks/&lt;task_id&gt;.json</code> stores status/pid/exit code; <code>tasks/&lt;task_id&gt;/output.log</code> stores output.</li><li><strong><code>cron/</code></strong>: scheduled task persistence; reloaded into the scheduler when the session is resumed with <code>kimi --session</code>. See <a href="./../reference/tools.html#scheduled-tasks">Scheduled tasks</a>.</li></ul><h2 id="built-in-tool-cache" tabindex="-1">Built-in tool cache <a class="header-anchor" href="#built-in-tool-cache" aria-label="Permalink to &quot;Built-in tool cache&quot;">​</a></h2><p>The first time the <code>Grep</code> tool needs ripgrep, the CLI can automatically download <code>rg</code> and cache it at <code>bin/rg</code> (<code>bin/rg.exe</code> on Windows). File-reference completion in the terminal UI uses <code>fd</code>; the CLI downloads and caches it at <code>bin/fd</code> (<code>bin/fd.exe</code> on Windows) in the background when needed. Subsequent runs reuse the cached binaries. <code>rg</code> prefers the system <code>PATH</code> before the cache, while <code>fd</code> checks the managed cache before falling back to system <code>fd</code> / <code>fdfind</code>. Deleting the <code>bin/</code> directory triggers a fresh download on the next use.</p><h2 id="logs-and-update-state" tabindex="-1">Logs and update state <a class="header-anchor" href="#logs-and-update-state" aria-label="Permalink to &quot;Logs and update state&quot;">​</a></h2><ul><li><strong><code>logs/kimi-code.log</code></strong> (global): records startup, login, export, and other cross-session events.</li><li><strong><code>&lt;sessionDir&gt;/logs/kimi-code.log</code></strong> (session-level): records diagnostic events within a single session.</li></ul><p>When reporting a bug, prefer exporting the relevant session with <code>kimi export</code> (see <a href="./../reference/kimi-command.html">kimi command</a>); the session log is included in the export by default. Add <code>--no-include-global-log</code> if you do not want to share the global log.</p><p>The files under <code>updates/</code> (<code>latest.json</code>, <code>install.json</code>, <code>install.lock</code>, <code>rollout.log</code>) are maintained automatically by the auto-update mechanism and normally do not need manual editing. <code>rollout.log</code> records which staged-rollout case each update check hit, which helps explain when a device will receive a new release.</p><h2 id="input-history" tabindex="-1">Input history <a class="header-anchor" href="#input-history" aria-label="Permalink to &quot;Input history&quot;">​</a></h2><p>Terminal input history is saved separately per working directory, at <code>user-history/&lt;md5(workDir)&gt;.jsonl</code>. It is used to browse previously typed prompts in the terminal UI using the arrow keys.</p><h2 id="clearing-data" tabindex="-1">Clearing data <a class="header-anchor" href="#clearing-data" aria-label="Permalink to &quot;Clearing data&quot;">​</a></h2><p>Deleting the data root directory (<code>~/.kimi-code/</code> or the path set by <code>KIMI_CODE_HOME</code>) removes all runtime data. To clear only part of the data:</p><table tabindex="0"><thead><tr><th>Goal</th><th>Action</th></tr></thead><tbody><tr><td>Reset configuration</td><td>Delete <code>~/.kimi-code/config.toml</code></td></tr><tr><td>Reset terminal UI preferences</td><td>Delete <code>~/.kimi-code/tui.toml</code></td></tr><tr><td>Clear all sessions</td><td>Delete <code>~/.kimi-code/sessions/</code> and <code>session_index.jsonl</code></td></tr><tr><td>Clear diagnostic logs</td><td>Delete <code>~/.kimi-code/logs/</code></td></tr><tr><td>Clear input history</td><td>Delete <code>~/.kimi-code/user-history/</code></td></tr><tr><td>Reset update state</td><td>Delete <code>~/.kimi-code/updates/latest.json</code></td></tr><tr><td>Force re-download of managed <code>rg</code> and <code>fd</code></td><td>Delete <code>~/.kimi-code/bin/</code></td></tr><tr><td>Clear provider OAuth login state</td><td>Run <code>/logout</code>, or delete the corresponding <code>credentials/&lt;name&gt;.json</code></td></tr><tr><td>Clear MCP server OAuth login state</td><td>Delete <code>credentials/mcp/</code> (<code>/logout</code> does not clear MCP credentials)</td></tr><tr><td>Remove user-level MCP declarations</td><td>Delete <code>$KIMI_CODE_HOME/mcp.json</code> (default <code>~/.kimi-code/mcp.json</code>)</td></tr><tr><td>Clear global Kimi-specific agent instructions</td><td>Delete <code>$KIMI_CODE_HOME/AGENTS.md</code> (default <code>~/.kimi-code/AGENTS.md</code>)</td></tr><tr><td>Clear plugin install records</td><td>Delete <code>$KIMI_CODE_HOME/plugins/</code> (local plugin source directories are not affected)</td></tr><tr><td>Clear Kimi-specific user-level Skills</td><td>Delete <code>$KIMI_CODE_HOME/skills/</code> (default <code>~/.kimi-code/skills/</code>)</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./config-files.html">Configuration files</a> — full reference for <code>config.toml</code> fields</li><li><a href="./env-vars.html">Environment variables</a> — detailed usage of <code>KIMI_CODE_HOME</code> and related path variables</li></ul>`,32)])])}const u=o(n,[["render",i]]);export{g as __pageData,u as default};
